<?php
chdir(__DIR__.'/..');$d=json_decode(file_get_contents('data/catalogue.json'),true);$report=[];$errors=[];
foreach($d['products'] as $p){if(!is_file($p['image'])){$errors[]=$p['model'].': missing image';continue;}$im=imagecreatefrompng($p['image']);$w=imagesx($im);$h=imagesy($im);$transparent=0;$visible=0;for($y=0;$y<$h;$y+=3)for($x=0;$x<$w;$x+=3){$a=(imagecolorat($im,$x,$y)>>24)&127;if($a===127)$transparent++;else $visible++;}if(!$transparent||!$visible)$errors[]=$p['model'].': invalid alpha content';foreach([[0,0],[$w-1,0],[0,$h-1],[$w-1,$h-1]] as [$x,$y])if(((imagecolorat($im,$x,$y)>>24)&127)!==127)$errors[]=$p['model'].': non-transparent corner';$report[]=['model'=>$p['model'],'path'=>$p['image'],'width'=>$w,'height'=>$h,'transparentSamples'=>$transparent,'visibleSamples'=>$visible];imagedestroy($im);}
$result=['products'=>count($report),'errors'=>$errors,'images'=>$report];file_put_contents('data/image-validation.json',json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));echo json_encode(['products'=>count($report),'errors'=>$errors]);exit($errors?1:0);
